"use strict";
/* Static viewer for JSON results generated by openEMS CI. */
const el = id => document.getElementById(id);
const PALETTE = {paper_bgcolor:"#101c2e",plot_bgcolor:"#101c2e",font:{color:"#d6e5f5",size:10}};
const PLOT_CFG = {responsive:true,displaylogo:false};
const DEG = Math.PI / 180;
let runs = [], active = null, field = null, mode = "combined", requestVersion = 0;
const DEFAULT_CAMERA={up:{x:0,y:0,z:1},center:{x:0,y:0,z:0},eye:{x:1.55,y:1.55,z:1.1}};
let sceneCamera=null,sceneDragMode="turntable",cameraEventsBound=false;
let orbitCenter=null; // Track the current pan target while orbiting.
let sceneRendering=false,sceneDirty=false,sceneFrameScheduled=false;
const POSE_AXIS_IDS=["px","py","pz","roll","pitch","yaw"];
const POSE_PRESETS={xy:[0,0,0],xz:[90,0,0],yz:[90,0,90]};
const lastValidPose={px:0,py:0,pz:0,roll:0,pitch:0,yaw:0};
const sliderOffsets={px:0,py:0,pz:0,roll:0,pitch:0,yaw:0};

function status(message){el("status").textContent = message}
function format(number,places=2){return Number.isFinite(number) ? Number(number).toFixed(places) : "—"}
async function getJSON(url){const r = await fetch(url); if(!r.ok) throw Error(url + ": HTTP " + r.status); return r.json()}
const add = (a,b)=>a.map((v,i)=>v+b[i]);
const scale = (a,s)=>a.map(v=>v*s);
const cross = (a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const magnitude = a=>Math.hypot(...a);
const normalize = a=>scale(a,1/(magnitude(a)||1));

function pose(){
 const keys = ["px","py","pz","roll","pitch","yaw"];
 const v = keys.map(k=>readPoseNumber(el(k).value)??lastValidPose[k]);
 return {position:v.slice(0,3).map(x=>Number.isFinite(x)?x:0),
         angles:v.slice(3).map(x=>(Number.isFinite(x)?x:0)*DEG)};
}
function rotate(p,a){
 // Extrinsic X-Y-Z, or Rz(yaw) * Ry(pitch) * Rx(roll)
 const [roll,pitch,yaw]=a;
 let [x,y,z]=p;
 [y,z]=[y*Math.cos(roll)-z*Math.sin(roll),y*Math.sin(roll)+z*Math.cos(roll)];
 [x,z]=[x*Math.cos(pitch)+z*Math.sin(pitch),-x*Math.sin(pitch)+z*Math.cos(pitch)];
 [x,y]=[x*Math.cos(yaw)-y*Math.sin(yaw),x*Math.sin(yaw)+y*Math.cos(yaw)];
 return [x,y,z];
}
function radiatingScale(){
 const preview=active?.geometry_preview||[];
 let extent=10;
 if(preview.length){
  for(const shape of preview){
   const points=shape.vertices||shape.points||[shape.start,shape.stop,shape.center].filter(Boolean);
   for(const point of points)for(const value of point)extent=Math.max(extent,Math.abs(Number(value)||0));
   extent=Math.max(extent,Number(shape.radius)||0);
  }
 }else{
  for(const g of active?.input_config?.geometry||[]){
   for(const point of [g.start,g.stop,g.center,g.origin].filter(Boolean))
    for(const value of point)extent=Math.max(extent,Math.abs(Number(value)||0));
   extent=Math.max(extent,Number(g.radius)||0);
  }
 }
 return extent*1.65; // Display scale only, NOT physical pattern radius
}
function materialColor(material){
 const mat=(active?.input_config?.materials||[]).find(x=>x.name===material);
 return mat?.type==="pec" ? "#e6b77b" : "#ab90e2";
}
function meshTrace(name,vertices,faces,color,opacity=.9){
 const x=vertices.map(v=>v[0]),y=vertices.map(v=>v[1]),z=vertices.map(v=>v[2]);
 return {type:"mesh3d",name,x,y,z,i:faces.map(f=>f[0]),j:faces.map(f=>f[1]),k:faces.map(f=>f[2]),
  color,opacity,flatshading:true,hovertemplate:name+"<extra></extra>",showlegend:false};
}
function boxTraces(g,idx){
 const [x0,y0,z0]=g.start,[x1,y1,z1]=g.stop;
 const vertices=[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],
 [x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]];
 const faces=[[0,1,2],[0,2,3],[4,6,5],[4,7,6],[0,4,5],[0,5,1],
  [1,5,6],[1,6,2],[2,6,7],[2,7,3],[3,7,4],[3,4,0]];
 const color=materialColor(g.material),name=g.material+" box "+(idx+1);
 const traces=[meshTrace(name,vertices,faces,color,.79)];
 // Visible edges, including zero-thickness PEC sheets.
 const edges=[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
 const x=[],y=[],z=[];
 for(const [a,b] of edges){for(const j of [a,b]){x.push(vertices[j][0]);y.push(vertices[j][1]);z.push(vertices[j][2])}x.push(null);y.push(null);z.push(null)}
 traces.push({type:"scatter3d",mode:"lines",name:name+" edges",x,y,z,
  line:{color,width:3},hoverinfo:"skip",showlegend:false});
 return traces;
}
function cylinderTraces(g,idx){
 const a=g.start,b=g.stop,axis=normalize(b.map((v,i)=>v-a[i]));
 const initial=Math.abs(axis[2])<.9?[0,0,1]:[1,0,0];
 const u=normalize(cross(axis,initial)),v=cross(axis,u);
 const n=24,vertices=[],faces=[],radius=Number(g.radius);
 for(const center of [a,b]){
  for(let i=0;i<n;i++){
   const t=2*Math.PI*i/n;
   vertices.push(add(center,add(scale(u,radius*Math.cos(t)),scale(v,radius*Math.sin(t)))));
  }
 }
 vertices.push(a,b);
 for(let i=0;i<n;i++){
  const j=(i+1)%n;
  faces.push([i,j,n+j],[i,n+j,n+i],[2*n,j,i],[2*n+1,n+i,n+j]);
 }
 return [meshTrace(g.material+" cylinder "+(idx+1),vertices,faces,materialColor(g.material),.94)];
}
function previewSphere(p,index){
 const vertices=[],faces=[],nphi=32,ntheta=16,r=p.radius,center=p.center;
 for(let i=0;i<=ntheta;i++){
  const theta=Math.PI*i/ntheta;
  for(let j=0;j<nphi;j++){
   const phi=2*Math.PI*j/nphi;
   vertices.push([center[0]+r*Math.sin(theta)*Math.cos(phi),
                  center[1]+r*Math.sin(theta)*Math.sin(phi),
                  center[2]+r*Math.cos(theta)]);
  }
 }
 for(let i=0;i<ntheta;i++)for(let j=0;j<nphi;j++){
  const j2=(j+1)%nphi,a=i*nphi+j,b=i*nphi+j2,c=(i+1)*nphi+j,d=(i+1)*nphi+j2;
  faces.push([a,c,d],[a,d,b]);
 }
 return meshTrace(p.name||"Sphere "+index,vertices,faces,materialColor(p.material),.85);
}
function previewWire(p,index){
 const points=p.points||[],radius=Number(p.radius)||.5;
 if(points.length<2)return [];
 const vertices=[],faces=[],n=12;
 for(let i=0;i<points.length;i++){
  const tangent=i===0?points[1].map((v,k)=>v-points[0][k]):
   i===points.length-1?points[i].map((v,k)=>v-points[i-1][k]):
   points[i+1].map((v,k)=>v-points[i-1][k]);
  const unit=normalize(tangent),trial=Math.abs(unit[2])<.9?[0,0,1]:[0,1,0];
  const u=normalize(cross(unit,trial)),v=cross(unit,u);
  for(let j=0;j<n;j++){
   const theta=2*Math.PI*j/n;
   vertices.push(add(points[i],add(scale(u,radius*Math.cos(theta)),scale(v,radius*Math.sin(theta)))));
  }
  if(i>0)for(let j=0;j<n;j++){
   const next=(j+1)%n,a=(i-1)*n+j,b=(i-1)*n+next,c=i*n+j,d=i*n+next;
   faces.push([a,b,d],[a,d,c]);
  }
 }
 return [meshTrace(p.name||"Wire "+index,vertices,faces,materialColor(p.material),.95)];
}
function geometryTraces(){
 const cfg=active?.input_config||{},traces=[],previews=active?.geometry_preview;
 if(Array.isArray(previews)){
  previews.forEach((p,i)=>{
   if(p.vertices&&p.faces?.length)traces.push(meshTrace(p.name||"Geometry "+i,p.vertices,p.faces,materialColor(p.material),.9));
   else if(p.shape==="wire"||p.shape==="helix")traces.push(...previewWire(p,i));
   else if(p.shape==="sphere"||p.shape==="spherical_shell")traces.push(previewSphere(p,i));
   else if(p.shape==="cylinder"||p.shape==="cylindrical_shell")
    traces.push(...cylinderTraces({...p,material:p.material},i));
   else if(p.vertices)traces.push(...boxTraces({start:[
    Math.min(...p.vertices.map(v=>v[0])),Math.min(...p.vertices.map(v=>v[1])),Math.min(...p.vertices.map(v=>v[2]))],
    stop:[Math.max(...p.vertices.map(v=>v[0])),Math.max(...p.vertices.map(v=>v[1])),Math.max(...p.vertices.map(v=>v[2]))],
    material:p.material},i));
  });
 }else{
  (cfg.geometry||[]).forEach((g,i)=>{
   if(g.shape==="box")traces.push(...boxTraces(g,i));
   if(g.shape==="cylinder")traces.push(...cylinderTraces(g,i));
  });
 }
 (cfg.ports||cfg.sources||[]).filter(p=>p.enabled!==false).forEach((p,i)=>{
  if(!p.start||!p.stop)return;
  traces.push({type:"scatter3d",mode:"lines+markers",name:"Feed "+(p.name||i+1),
   x:[p.start[0],p.stop[0]],y:[p.start[1],p.stop[1]],z:[p.start[2],p.stop[2]],
   line:{color:p.excite===false?"#bac5d9":"#fb6f80",width:7},
   marker:{color:"#ff6177",size:4},
   hovertemplate:"Port "+(p.name||i+1)+"<extra></extra>"});
 });
 return traces;
}
// Use the same sampled surface for the 3D pattern and plane intersection.
function patternGrid(p){
 const th=p.theta_deg.map(t=>t*DEG),ph=p.phi_deg.map(t=>t*DEG);
 const vertices=[],directivity=[],peak=Number(p.max_directivity_dbi),visual=radiatingScale();
 for(let i=0;i<th.length;i++){
  const row=[],db=[];
  for(let j=0;j<ph.length;j++){
   const d=Number(p.directivity_dbi[i][j]);
   const r=visual*Math.pow(10,(d-peak)/10);
   row.push([r*Math.sin(th[i])*Math.cos(ph[j]),
             r*Math.sin(th[i])*Math.sin(ph[j]),
             r*Math.cos(th[i])]);
   db.push(d);
  }
  vertices.push(row);directivity.push(db);
 }
 return {vertices,directivity};
}
function patternTrace(p,grid=patternGrid(p)){
 const x=[],y=[],z=[],db=[];
 const rows=grid.vertices,levels=grid.directivity;
 if(!rows.length||!rows[0].length)return null;
 for(let i=0;i<rows.length;i++){
  const xx=[],yy=[],zz=[],dd=[];
  for(let j=0;j<=rows[i].length;j++){
   const k=j%rows[i].length,point=rows[i][k];
   xx.push(point[0]);yy.push(point[1]);zz.push(point[2]);dd.push(levels[i][k]);
  }
  x.push(xx);y.push(yy);z.push(zz);db.push(dd);
 }
 return {type:"surface",name:"Directivity",x,y,z,surfacecolor:db,colorscale:"Viridis",
  colorbar:{title:"dBi",thickness:10,len:.65},opacity:.52,
  hovertemplate:"Directivity %{surfacecolor:.2f} dBi<extra></extra>",showscale:true};
}
// Exact intersection of each sampled surface triangle with the posed plane.
// This is a section of the *display-scaled* far-field surface, not the antenna.
function trianglePlaneSegment(triangle,origin,normal,epsilon){
 const d=triangle.map(pt=>pt.reduce((sum,c,i)=>sum+(c-origin[i])*normal[i],0));
 if(d.every(distance=>Math.abs(distance)<=epsilon))return null;
 const intersections=[];
 const addPoint=point=>{
  if(!intersections.some(p=>magnitude(p.map((v,i)=>v-point[i]))<=epsilon))
   intersections.push(point);
 };
 for(const [a,b] of [[0,1],[1,2],[2,0]]){
  if(Math.abs(d[a])<=epsilon)addPoint(triangle[a]);
  if(d[a]*d[b]<0 && Math.abs(d[a])>epsilon && Math.abs(d[b])>epsilon){
   const t=d[a]/(d[a]-d[b]);
   addPoint(triangle[a].map((value,k)=>value+t*(triangle[b][k]-value)));
  }
 }
 if(intersections.length<2)return null;
 if(intersections.length===2)return intersections;
 // If the plane contains an edge or passes through vertices, retain the
 // longest segment rather than accidentally producing a triangle.
 let best=null,length=-1;
 for(let i=0;i<intersections.length;i++)
  for(let j=i+1;j<intersections.length;j++){
   const dist=magnitude(intersections[i].map((v,k)=>v-intersections[j][k]));
   if(dist>length){length=dist;best=[intersections[i],intersections[j]];}
  }
 return best;
}
// Cache the radiation surface; sliding a plane should not rebuild the
// entire far-field mesh on every pointer movement.
let cachedField=null,cachedGrid=null;
function cachedPatternGrid(p){
 if(cachedField!==p){cachedField=p;cachedGrid=patternGrid(p);}
 return cachedGrid;
}
// Join triangle/plane segments into ordered, continuous polylines. Shared
// triangle edges are deduplicated, including the seam and the theta=90 ring.
function stitchSectionSegments(segments,tolerance){
 const nodes=[],adjacency=[],edges=[],buckets=new Map();
 const cell=point=>point.map(v=>Math.floor(v/tolerance));
 const bucketKey=idx=>idx.join(",");
 function nodeFor(point){
  const c=cell(point);
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)for(let dz=-1;dz<=1;dz++){
   for(const i of buckets.get(bucketKey([c[0]+dx,c[1]+dy,c[2]+dz]))||[]){
    if(magnitude(nodes[i].map((v,k)=>v-point[k]))<=tolerance)return i;
   }
  }
  const id=nodes.length,key=bucketKey(c);
  nodes.push(point.slice());adjacency.push([]);
  if(!buckets.has(key))buckets.set(key,[]);
  buckets.get(key).push(id);
  return id;
 }
 const seen=new Set();
 for(const [a,b] of segments){
  const i=nodeFor(a),j=nodeFor(b);
  if(i===j)continue;
  const key=i<j?i+","+j:j+","+i;
  if(seen.has(key))continue;
  seen.add(key);
  const id=edges.length;
  edges.push([i,j]);adjacency[i].push(id);adjacency[j].push(id);
 }
 const used=new Set(),contours=[];
 function walk(start,firstEdge){
  const path=[start];
  let current=start,prior=-1,edge=firstEdge;
  while(edge!==undefined&&!used.has(edge)){
   used.add(edge);
   const [a,b]=edges[edge],next=a===current?b:a;
   path.push(next);
   if(next===start)break;
   const choices=adjacency[next].filter(index=>!used.has(index));
   if(!choices.length)break;
   // At a high-degree vertex continue in the direction closest to a
   // straight line, avoiding spurious branches from coplanar triangles.
   if(choices.length===1)edge=choices[0];
   else{
    const travel=nodes[next].map((value,k)=>value-nodes[current][k]);
    const norm=magnitude(travel)||1;
    edge=choices.reduce((best,index)=>{
     const [u,v]=edges[index],other=u===next?v:u;
     const direction=nodes[other].map((value,k)=>value-nodes[next][k]);
     const score=direction.reduce((sum,value,k)=>sum+value*travel[k],0)/(norm*(magnitude(direction)||1));
     return score>best.score?{index,score}:best;
    },{index:choices[0],score:-Infinity}).index;
   }
   prior=current;current=next;
  }
  if(path.length>=2)contours.push(path.map(id=>nodes[id]));
 }
 // Open paths first; then any remaining closed loops.
 for(let i=0;i<nodes.length;i++){
  if(adjacency[i].length!==2){
   for(const edge of adjacency[i])if(!used.has(edge))walk(i,edge);
  }
 }
 for(let i=0;i<edges.length;i++)if(!used.has(i))walk(edges[i][0],i);
 return contours;
}
function smoothSectionContour(points,epsilon){
 if(points.length<3)return points;
 const closed=magnitude(points[0].map((v,k)=>v-points[points.length-1][k]))<epsilon;
 const original=closed?points.slice(0,-1):points;
 if(original.length<3)return points;
 // One Chaikin pass rounds mesh facets without splitting the 3D polyline.
 const smooth=[];
 if(!closed)smooth.push(original[0]);
 const count=closed?original.length:original.length-1;
 for(let i=0;i<count;i++){
  const a=original[i],b=original[(i+1)%original.length];
  smooth.push(a.map((v,k)=>.75*v+.25*b[k]),a.map((v,k)=>.25*v+.75*b[k]));
 }
 if(closed)smooth.push(smooth[0]);else smooth.push(original[original.length-1]);
 return smooth;
}
function patternPlaneIntersection(grid,position,angles){
 const rows=grid.vertices;
 if(rows.length<2||rows[0].length<3)return [];
 const normal=rotate([0,0,1],angles),epsilon=Math.max(1e-8,radiatingScale()*1e-7);
 const segments=[];
 const append=triangle=>{
  const section=trianglePlaneSegment(triangle,position,normal,epsilon);
  if(section)segments.push(section);
 };
 for(let i=0;i<rows.length-1;i++){
  const n=Math.min(rows[i].length,rows[i+1].length);
  for(let j=0;j<n;j++){
   const next=(j+1)%n,a=rows[i][j],b=rows[i][next],c=rows[i+1][j],d=rows[i+1][next];
   append([a,b,c]);append([b,d,c]);
  }
 }
 if(!segments.length)return [];
 const contours=stitchSectionSegments(segments,epsilon*8);
 const x=[],y=[],z=[];
 for(const points of contours){
  if(points.length<2)continue;
  // Smoothing is display-only; the original intersections are computed
  // against the actual sampled radiation surface.
  const contour=smoothSectionContour(points,epsilon*8);
  for(const pt of contour){x.push(pt[0]);y.push(pt[1]);z.push(pt[2]);}
  x.push(null);y.push(null);z.push(null);
 }
 if(!x.length)return [];
 const base={type:"scatter3d",mode:"lines",x,y,z,hoverinfo:"skip",showlegend:false};
 return [
  {...base,name:"Section outline",line:{color:"#24304b",width:12}},
  {...base,name:"Continuous plane intersection",line:{color:"#fff1a1",width:6}}
 ];
}
function planeTraces(){
 const p=pose(),radius=radiatingScale(),u=rotate([1,0,0],p.angles),v=rotate([0,1,0],p.angles);
 const point=(x,y)=>add(p.position,add(scale(u,radius*x),scale(v,radius*y)));
 const pts=[point(-1,-1),point(1,-1),point(1,1),point(-1,1)];
 return [
  meshTrace("Display cutting plane",pts,[[0,1,2],[0,2,3]],"#f6b45c",.17),
  {type:"scatter3d",mode:"lines",x:[pts[0][0],pts[1][0],pts[2][0],pts[3][0],pts[0][0]],
   y:[pts[0][1],pts[1][1],pts[2][1],pts[3][1],pts[0][1]],
   z:[pts[0][2],pts[1][2],pts[2][2],pts[3][2],pts[0][2]],
   line:{width:4,color:"#f6b45c"},hoverinfo:"skip",showlegend:false}
 ];
}
function sceneTraces(){
 const geom=el("showGeometry").checked,rad=el("showRadiation").checked,plane=el("showPlane").checked;
 const traces=[];
 // Compute the surface once so the highlighted section matches the same mesh.
 const grid=rad&&field?cachedPatternGrid(field):null;
 if(grid){const pattern=patternTrace(field,grid);if(pattern)traces.push(pattern);}
 if(geom)traces.push(...geometryTraces());
 if(plane){
  traces.push(...planeTraces());
  if(grid){
   const p=pose();
   traces.push(...patternPlaneIntersection(grid,p.position,p.angles));
  }
 }
 return traces;
}
// Plotly's _fullLayout.scene.camera can lag the live WebGL camera
// after turntable orbit and wheel zoom. Read the real GL camera first.
function copyCamera(camera){
 if(!camera?.eye||!camera.center)return null;
 const c={
  eye:{x:Number(camera.eye.x),y:Number(camera.eye.y),z:Number(camera.eye.z)},
  center:{x:Number(camera.center.x),y:Number(camera.center.y),z:Number(camera.center.z)},
  up:{x:0,y:0,z:1}
 };
 if(Object.values(c.eye).some(v=>!Number.isFinite(v))||
    Object.values(c.center).some(v=>!Number.isFinite(v)))return null;
 if(camera.projection?.type)c.projection={type:camera.projection.type};
 return c;
}
function captureCamera(){
 const graph=el("farfield");
 const live=graph?._fullLayout?.scene?._scene;
 let camera=null;
 if(live&&typeof live.getCamera==="function"){
  try{camera=copyCamera(live.getCamera());}
  catch(error){console.warn("Live 3D camera unavailable",error);}
 }
 camera ||= copyCamera(graph?._fullLayout?.scene?.camera);
 camera ||= copyCamera(sceneCamera);
 sceneCamera=camera||copyCamera(DEFAULT_CAMERA);
 return copyCamera(sceneCamera);
}
function rememberCamera(event){
 if(!event)return;
 const changed=Object.keys(event).some(key=>key==="scene.camera"||key.startsWith("scene.camera."));
 if(!changed)return;
 const next=copyCamera(event["scene.camera"])||captureCamera();
 if(sceneDragMode==="pan")orbitCenter={...next.center};
 else if(orbitCenter)next.center={...orbitCenter};
 sceneCamera=next;
 updateAxisGizmo(next);
}
function zoomCamera(factor){
 if(!(factor>0))return Promise.resolve();
 const camera=captureCamera();
 const distance=magnitude(Object.values(camera.eye));
 const target=Math.max(.3,Math.min(15,distance*factor));
 const next={...camera,eye:Object.fromEntries(
  Object.entries(camera.eye).map(([axis,value])=>[axis,value*target/(distance||1)]))};
 sceneCamera=next;
 return Plotly.relayout(el("farfield"),{"scene.camera":next});
}
const dot=(a,b)=>a.reduce((sum,v,i)=>sum+v*b[i],0);
const WORLD_AXES={x:[1,0,0],y:[0,1,0],z:[0,0,1]};
function cameraBasis(camera){
 const eye=[camera.eye.x,camera.eye.y,camera.eye.z];
 const view=magnitude(eye)>1e-6?normalize(eye):normalize([1,1,1]);
 let right=cross([0,0,1],view);
 if(magnitude(right)<1e-3)right=[1,0,0];
 right=normalize(right);
 return {view,right,screenUp:normalize(cross(view,right))};
}
function projectWorldAxis(camera,axis){
 const basis=cameraBasis(camera),world=WORLD_AXES[axis];
 if(!world)return {x:0,y:-1,depth:0};
 return {x:dot(world,basis.right),y:-dot(world,basis.screenUp),depth:dot(world,basis.view)};
}
function axisDragDirection(camera,axis){
 const p=projectWorldAxis(camera,axis),length=Math.hypot(p.x,p.y);
 return length<.06?[0,-1]:[p.x/length,p.y/length];
}
function updateAxisGizmo(camera=sceneCamera||DEFAULT_CAMERA){
 if(!camera||!el("viewAxes"))return;
 for(const axis of ["x","y","z"]){
  const p=projectWorldAxis(camera,axis),length=Math.hypot(p.x,p.y);
  const x=72+(length<.12?(axis==="x"?-8:axis==="y"?8:0):p.x*47);
  const y=70+(length<.12?0:p.y*47);
  const line=el("axisLine"+axis.toUpperCase());
  line.setAttribute("x2",String(x));line.setAttribute("y2",String(y));
  line.setAttribute("opacity",p.depth<-.1?".57":"1");
  const grip=el("viewAxes").querySelector('[data-pan-axis="'+axis+'"]');
  grip.style.left=x+"px";grip.style.top=(y+24)+"px";
  grip.style.zIndex=String(Math.round((p.depth+1)*10)+10);
  grip.title="World "+axis.toUpperCase()+" · hold and drag to pan";
 }
}
function axisPanAmount(camera,axis,dx,dy,viewPixels){
 const [sx,sy]=axisDragDirection(camera,axis);
 const projected=dx*sx+dy*sy;
 const eyeDistance=magnitude(Object.values(camera.eye));
 const scaleFactor=Math.max(.6,Math.min(3,eyeDistance));
 return -projected*1.6*scaleFactor/Math.max(160,viewPixels);
}
function setupAxisPan(){
 for(const button of document.querySelectorAll("[data-pan-axis]")){
  const axis=button.dataset.panAxis;
  let gesture=null,framePending=false,frameCamera=null;
  const apply=()=>{
   framePending=false;
   if(!frameCamera)return;
   const next=frameCamera;frameCamera=null;
   sceneCamera=next;
   Plotly.relayout(el("farfield"),{"scene.camera":next}).catch(error=>console.error("3D pan error",error));
  };
  const queue=next=>{
   frameCamera=next;sceneCamera=next;
   orbitCenter={...next.center};
   if(!framePending){framePending=true;requestAnimationFrame(apply);}
  };
  button.addEventListener("pointerdown",event=>{
   if(event.pointerType==="mouse"&&event.button!==0)return;
   event.preventDefault();
   gesture={pointer:event.pointerId,x:event.clientX,y:event.clientY,
            camera:captureCamera()};
   button.setPointerCapture(event.pointerId);
   button.classList.add("dragging");
  });
  button.addEventListener("pointermove",event=>{
   if(!gesture||gesture.pointer!==event.pointerId)return;
   event.preventDefault();
   const width=Math.min(el("farfield").clientWidth||400,el("farfield").clientHeight||400);
   const amount=axisPanAmount(gesture.camera,axis,
                            event.clientX-gesture.x,event.clientY-gesture.y,width);
   const next={...gesture.camera,center:{...gesture.camera.center}};
   next.center[axis]=Math.max(-10,Math.min(10,next.center[axis]+amount));
   queue(next);
  });
  const release=event=>{
   if(!gesture||gesture.pointer!==event.pointerId)return;
   gesture=null;
   button.classList.remove("dragging");
   if(button.hasPointerCapture(event.pointerId))button.releasePointerCapture(event.pointerId);
  };
  button.addEventListener("pointerup",release);
  button.addEventListener("pointercancel",release);
  button.addEventListener("lostpointercapture",release);
  // Arrow keys allow incremental world-axis panning without a pointer.
  button.addEventListener("keydown",event=>{
   if(!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(event.key))return;
   event.preventDefault();
   const camera=captureCamera(),step=(event.key==="ArrowLeft"||event.key==="ArrowDown")?-.06:.06;
   const next={...camera,center:{...camera.center}};
   next.center[axis]=Math.max(-10,Math.min(10,next.center[axis]+step));
   queue(next);
  });
 }
}
async function renderScene(){
 if(!active||!field)return;
 sceneDirty=true;
 if(sceneRendering)return;
 sceneRendering=true;
 try{
  do{
   sceneDirty=false;
   // Synchronize with the live WebGL view before any data or plane redraw.
   // Avoid accidentally restoring a stale, pre-pan camera.
   if(sceneCamera!==null)captureCamera();
   await Plotly.react("farfield",sceneTraces(),
    {...PALETTE,margin:{l:0,r:0,t:0,b:0},uirevision:"z-up-camera-preserved-v3",
     scene:{aspectmode:"data",bgcolor:"#101c2e",
      dragmode:sceneDragMode,camera:sceneCamera||DEFAULT_CAMERA,
      xaxis:{title:"X (mm)",gridcolor:"#253c56",zerolinecolor:"#395775"},
      yaxis:{title:"Y (mm)",gridcolor:"#253c56",zerolinecolor:"#395775"},
      zaxis:{title:"Z (mm)",gridcolor:"#253c56",zerolinecolor:"#395775"}}},
    {...PLOT_CFG,displayModeBar:false,scrollZoom:true,doubleClick:false});
   if(!cameraEventsBound&&typeof el("farfield").on==="function"){
    el("farfield").on("plotly_relayout",rememberCamera);
    cameraEventsBound=true;
   }
   updateAxisGizmo(captureCamera());
  }while(sceneDirty);
 }finally{
  sceneRendering=false;
 }
}
// Coalesce pointer-driven changes into one 3D re-render per animation frame.
function scheduleSceneRender(){
 if(sceneFrameScheduled)return;
 sceneFrameScheduled=true;
 requestAnimationFrame(()=>{
  sceneFrameScheduled=false;
  renderScene().catch(error=>{status("3D plot error: "+error.message);console.error(error)});
 });
}
async function changeCameraTool(next){
 if(next!=="pan"&&next!=="turntable")return;
 sceneDragMode=next;
 for(const [id,tool] of [["orbitView","turntable"],["panView","pan"]]){
  const btn=el(id),selected=tool===next;
  btn.classList.toggle("active",selected);
  btn.setAttribute("aria-pressed",String(selected));
 }
 // Persist the live camera with the panned target as the orbit pivot.
 const camera=captureCamera();
 orbitCenter={...camera.center};
 updateAxisGizmo(camera);
 if(el("farfield")._fullLayout)
  await Plotly.relayout(el("farfield"),{"scene.dragmode":next});
}
async function resetCamera(){
 sceneCamera={
  up:{...DEFAULT_CAMERA.up},
  center:{...DEFAULT_CAMERA.center},
  eye:{...DEFAULT_CAMERA.eye}
 };
 orbitCenter={...sceneCamera.center};
 updateAxisGizmo(sceneCamera);
 if(el("farfield")._fullLayout)
  await Plotly.relayout("farfield",{"scene.camera":sceneCamera});
}
function formatPoseNumber(value){
 // Explicit ASCII + / - and two decimal places, including on mobile.
 return (value>=0?"+":"")+value.toFixed(2);
}
function readPoseNumber(value){
 const text=String(value).trim().replace(/\u2212/g,"-");
 if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(text))return null;
 const num=Number(text);
 return Number.isFinite(num)&&Math.abs(num)<=1000000?num:null;
}
// Uniformly spaced detents map to ±1, ±2, ±4, ±8 in world units.
function logarithmicJogOffset(detent){
 const n=Math.max(-4,Math.min(4,Math.round(detent)));
 return n===0?0:Math.sign(n)*Math.pow(2,Math.abs(n)-1);
}
function resetIncrementalSlider(id){
 sliderOffsets[id]=0;
 const slider=el(id+"Slider");
 slider.value="0";
 slider.setAttribute("aria-valuetext","0 "+(["px","py","pz"].includes(id)?"mm":"°"));
}
function resetIncrementalSliders(){
 for(const id of POSE_AXIS_IDS)resetIncrementalSlider(id);
}
function applyIncrementalSlider(id,detent){
 if(!Number.isFinite(detent))return;
 const offset=logarithmicJogOffset(detent);
 const delta=offset-sliderOffsets[id];
 sliderOffsets[id]=offset;
 const slider=el(id+"Slider");
 const unit=["px","py","pz"].includes(id)?"mm":"°";
 slider.setAttribute("aria-valuetext",(offset>=0?"+":"")+offset+" "+unit);
 if(delta!==0){
  setPoseAxis(id,lastValidPose[id]+delta);
  if(!["px","py","pz"].includes(id))updatePresetButtons();
  scheduleSceneRender();
 }
}
function setPoseAxis(id,value){
 if(!Number.isFinite(value)||Math.abs(value)>1000000)return;
 lastValidPose[id]=value;
 const input=el(id);
 input.value=formatPoseNumber(value);
 input.removeAttribute("aria-invalid");
}
function updatePresetButtons(){
 const values=["roll","pitch","yaw"].map(id=>readPoseNumber(el(id).value));
 for(const button of document.querySelectorAll("[data-plane]")){
  const preset=POSE_PRESETS[button.dataset.plane];
  const selected=preset&&values.every((v,i)=>v!==null&&Math.abs(v-preset[i])<.001);
  button.classList.toggle("active",Boolean(selected));
  button.setAttribute("aria-pressed",String(Boolean(selected)));
 }
}
async function renderS11(){
 const s=active.s11,x=s.frequency_hz.map(f=>f/1e9);
 await Plotly.react("s11Plot",[
  {x,y:s.logmag_db,type:"scatter",mode:"lines",name:"|S11| dB",line:{color:"#61dce5",width:2}},
  {x,y:s.phase_deg,type:"scatter",mode:"lines",name:"Phase °",yaxis:"y2",line:{color:"#ffba79",width:2}}
 ],{...PALETTE,margin:{l:53,r:49,t:27,b:35},
  legend:{orientation:"h",x:0,y:1.23,font:{size:10}},
  xaxis:{title:"Frequency (GHz)",gridcolor:"#263e57"},
  yaxis:{title:"dB",gridcolor:"#263e57",titlefont:{color:"#61dce5"}},
  yaxis2:{title:"°",side:"right",overlaying:"y",range:[-180,180],titlefont:{color:"#ffba79"}}},PLOT_CFG);
 await Plotly.react("vswrPlot",[{x,y:s.vswr,type:"scatter",mode:"lines",
  line:{color:"#60d7bc",width:2},hovertemplate:"%{x:.4f} GHz: %{y:.2f}<extra></extra>"}],
 {...PALETTE,margin:{l:53,r:14,t:10,b:32},
  xaxis:{title:"Frequency (GHz)",gridcolor:"#263e57"},
  yaxis:{title:"VSWR",gridcolor:"#263e57",rangemode:"tozero",autorange:true}},PLOT_CFG);
}
async function renderPattern(){
 const seq=++requestVersion;
 try{
  if(!active)return;
  status("Loading pattern…");
  const pattern=active.patterns[Number(el("freq").value)];
  const path=el("run").value.replace(/result\.json$/,"");
  const f=await getJSON(path+pattern.file);
  if(seq!==requestVersion)return;
  field=f;
  el("peak").textContent="Peak "+format(f.max_directivity_dbi)+" dBi";
  el("eff").textContent=Number.isFinite(f.radiation_efficiency) ?
   "Efficiency "+format(100*f.radiation_efficiency,1)+"%" : "Efficiency n/a";
  await renderScene();
  status("Ready · "+format(f.frequency_hz/1e9,3)+" GHz");
 }catch(error){status("Pattern error: "+error.message);console.error(error)}
}
async function renderRun(){
 const seq=++requestVersion;
 try{
  status("Loading simulation…");field=null;
  const result=await getJSON(el("run").value);
  if(seq!==requestVersion)return;
  active=result;
  // A different antenna should be framed initially from the default camera;
  // frequency changes and plane edits retain the existing view.
  sceneCamera=null;
  orbitCenter=null;
  updateAxisGizmo(DEFAULT_CAMERA);
  cachedField=null;
  resetIncrementalSliders();
  el("mesh").textContent=Number(active.mesh_total_cells).toLocaleString()+" cells";
  el("config").textContent=JSON.stringify(active.input_config,null,2);
  el("freq").replaceChildren(...active.patterns.map((p,index)=>{
   const option=document.createElement("option");
   option.value=index;option.textContent=format(p.frequency_hz/1e9,3)+" GHz";return option;
  }));
  await renderS11();
  await renderPattern();
 }catch(error){status("Result error: "+error.message);console.error(error)}
}
function setMode(next){
 mode=next;document.body.dataset.mode=next;
 for(const button of document.querySelectorAll(".view-tabs button")){
  button.classList.toggle("active",button.dataset.mode===next);
 }
 el("showGeometry").checked=next!=="radiation";
 el("showRadiation").checked=next!=="geometry";
 el("showPlane").checked=next==="combined";
 scheduleSceneRender();
 setTimeoutResize();
}
function setTimeoutResize(){
 requestAnimationFrame(()=>{
  for(const id of ["farfield","s11Plot","vswrPlot"]){
   const graph=el(id);
   if(graph?._fullLayout)Plotly.Plots.resize(graph);
  }
 });
}
(function setupControls(){
 for(const [id,dragmode] of [["orbitView","turntable"],["panView","pan"]]){
  el(id).addEventListener("click",()=>changeCameraTool(dragmode));
 }
 el("resetView").addEventListener("click",resetCamera);
 el("zoomIn").addEventListener("click",()=>zoomCamera(.8));
 el("zoomOut").addEventListener("click",()=>zoomCamera(1.25));
 setupAxisPan();
 for(const button of document.querySelectorAll(".view-tabs button")){
  button.addEventListener("click",()=>setMode(button.dataset.mode));
 }
 for(const id of ["showGeometry","showRadiation","showPlane"])
  el(id).addEventListener("change",scheduleSceneRender);

 for(const id of POSE_AXIS_IDS){
  const input=el(id),slider=el(id+"Slider");
  slider.addEventListener("input",()=>applyIncrementalSlider(id,Number(slider.value)));
  // Re-center after pointer, touch, keyboard or assistive input ends.
  for(const eventName of ["pointerup","pointercancel","touchend","touchcancel","keyup","change","blur"]){
   slider.addEventListener(eventName,()=>resetIncrementalSlider(id));
  }
  input.addEventListener("input",()=>{
   const number=readPoseNumber(input.value);
   if(number===null){
    input.setAttribute("aria-invalid","true");
    return; // Allow a partial input such as "-" while typing.
   }
   lastValidPose[id]=number;
   input.removeAttribute("aria-invalid");
   resetIncrementalSlider(id);
   if(!["px","py","pz"].includes(id))updatePresetButtons();
   scheduleSceneRender();
  });
  input.addEventListener("blur",()=>{
   const value=readPoseNumber(input.value);
   setPoseAxis(id,value===null?lastValidPose[id]:value);
   resetIncrementalSlider(id);
   if(!["px","py","pz"].includes(id))updatePresetButtons();
   scheduleSceneRender();
  });
  input.addEventListener("keydown",event=>{
   if(event.key==="Enter"){event.preventDefault();input.blur();}
   if(event.key==="Escape"){
    input.value=formatPoseNumber(lastValidPose[id]);input.blur();
   }
  });
 }
 el("poseReset").addEventListener("click",()=>{
  for(const id of POSE_AXIS_IDS)setPoseAxis(id,0);
  resetIncrementalSliders();
  el("showPlane").checked=true;
  updatePresetButtons();
  scheduleSceneRender();
 });
 for(const preset of document.querySelectorAll("[data-plane]")){
  preset.addEventListener("click",()=>{
   const angles=POSE_PRESETS[preset.dataset.plane];
   if(!angles)return;
   ["roll","pitch","yaw"].forEach((id,index)=>setPoseAxis(id,angles[index]));
   ["roll","pitch","yaw"].forEach(resetIncrementalSlider);
   el("showPlane").checked=true;
   updatePresetButtons();
   scheduleSceneRender();
  });
 }
 updatePresetButtons();
})();
(async function init(){
 try{
  if(!window.Plotly)throw Error("Plotly library is unavailable");
  runs=(await getJSON("./manifest.json")).runs;
  if(!runs.length){status("No published results yet");return}
  el("run").replaceChildren(...runs.map(run=>{
   const option=document.createElement("option");option.value=run.path;option.textContent=run.name;return option;
  }));
  await renderRun();
 }catch(error){status("Viewer error: "+error.message);console.error(error)}
})();
